"""Append observation-only retained-FD reachability to the full abc9 graph."""
from pathlib import Path
import argparse,ast,hashlib,json
SHA=lambda v:hashlib.sha256(v).hexdigest()
PINS={"Cargo.toml":"9d95c6f534a0a5cd1b21dde659ebe2ed02c0ba7d52d5bc792118ec32d615ff14","Cargo.lock":"b868d2529f17dfb78ba390e078eb281a98d9850e4eaa12245739fec43ec97823","src/mcp/runtime/request_audit.rs":"b5189f2923153ffa83d0b45a7cdf89873b0f17ebbe6ec1b174c05bab291d73da","src/mcp/runtime/request_archive_store.rs":"efecc499d8032f06230e5048dfe2daf65d74560ab171aed707c187653e511c48","src/mcp/runtime/request_archive_store_tests.rs":"95d6ebd4a7a8eede5f254b051a8447e98735cd38a9882248228e24574c7308a7"}
STORE_APPEND="\n// Qualification-only reachability for the unchanged retained legacy anchor.\nfn __hia_anchor_mutation(root:&std::path::Path, mode:&str, original:&[u8])->std::io::Result<()> {\n use std::os::unix::fs::PermissionsExt;\n let path=root.join(ARCHIVE_ANCHOR);let alias=root.join(\"qualification-held-anchor\");\n let write=|bytes:&[u8]|->std::io::Result<()> {\n  let mut file=std::fs::OpenOptions::new().write(true).create(true).truncate(true).open(&path)?;\n  file.set_permissions(std::fs::Permissions::from_mode(0o600))?;\n  std::io::Write::write_all(&mut file,bytes)?;file.sync_all()\n };\n let changed=|| {let mut value=original.to_vec();let i=value.iter().rposition(u8::is_ascii_digit).unwrap();value[i]=if value[i]==b'1'{b'2'}else{b'1'};value};\n match mode {\n  \"none\"=>Ok(()),\n  \"replace\"=>{std::fs::rename(&path,&alias)?;write(original)},\n  \"different_replace\"=>{std::fs::rename(&path,&alias)?;write(&changed())},\n  \"missing\"=>std::fs::remove_file(&path),\n  \"mode\"=>std::fs::set_permissions(&path,std::fs::Permissions::from_mode(0o644)),\n  \"link\"=>std::fs::hard_link(&path,&alias),\n  \"symlink\"=>{std::fs::rename(&path,&alias)?;std::os::unix::fs::symlink(&alias,&path)},\n  \"rewrite\"=>write(&changed()),\n  \"rewrite_restore_mtime\"=>{let before=std::fs::metadata(&path)?;write(&changed())?;std::fs::OpenOptions::new().write(true).open(&path)?.set_times(std::fs::FileTimes::new().set_modified(before.modified()?))},\n  \"truncate\"=>write(b\"{\"),\n  \"touch\"=>{let before=std::fs::metadata(&path)?;std::fs::OpenOptions::new().write(true).open(&path)?.set_times(std::fs::FileTimes::new().set_modified(before.modified()?+std::time::Duration::from_secs(1)))},\n  \"rename_back\"=>{std::fs::rename(&path,&alias)?;write(original)?;std::fs::remove_file(&path)?;std::fs::rename(&alias,&path)},\n  \"root_replace\"=>{let held=root.with_extension(\"qualification-held-root\");std::fs::rename(root,&held)?;std::fs::create_dir(root)?;std::fs::set_permissions(root,std::fs::Permissions::from_mode(0o700))?;write(original)},\n  _=>panic!(\"unknown qualification mutation\"),\n }\n}\nfn __hia_anchor_original_error(error:&anyhow::Error)->serde_json::Value{\n let io=error.downcast_ref::<std::io::Error>();\n serde_json::json!({\"text\":error.to_string(),\"io_errno\":io.and_then(std::io::Error::raw_os_error),\"io_kind\":io.map(|e|format!(\"{:?}\",e.kind()))})\n}\npub(super) fn __hia_archive_anchor_fs_original(value:&serde_json::Value)->serde_json::Value{\n use std::io::Seek;\n use std::os::unix::fs::FileExt;\n let path=std::path::Path::new(value[\"root\"].as_str().unwrap());\n let root=File::open(path).unwrap();\n let mut pinned=match PinnedAnchor::open(&root){\n  Ok(value)=>value,\n  Err(error)=>return serde_json::json!({\"phase\":\"open\",\"accepted\":false,\"error\":__hia_anchor_original_error(&error)}),\n };\n let wire=__hia_anchor_wire(1,0,[pinned.record.root_device,pinned.record.root_inode],\n  [pinned.record.archive_device,pinned.record.archive_inode],None,&[]);\n let original=pinned.bytes.to_vec();let position=(&pinned.file).stream_position().unwrap();\n __hia_anchor_mutation(path,value[\"before\"].as_str().unwrap_or(\"none\"),&original).unwrap();\n if value[\"refresh_stamp\"].as_bool().unwrap_or(false){pinned.stamp=AnchorStamp::held(&pinned.file).unwrap();}\n let repeats=value[\"repeats\"].as_u64().unwrap_or(1);let during=value[\"during\"].as_str().unwrap_or(\"none\");\n let mut callbacks=0u64;let mut completed=0u64;let mut error=None;\n for _ in 0..repeats {\n  let result=if during==\"none\"{pinned.fence(&root)}else{\n   pinned.fence_with(&root,|file,bytes|{\n    callbacks+=1;\n    if during==\"before_read_truncate\"{__hia_anchor_mutation(path,\"truncate\",&original)?;}\n    file.read_exact_at(bytes,0)?;\n    if let Some(mutation)=during.strip_prefix(\"after_read_\"){__hia_anchor_mutation(path,mutation,&original)?;}\n    Ok(())\n   })\n  };\n  match result {Ok(())=>completed+=1,Err(e)=>{error=Some(__hia_anchor_original_error(&e));break;}}\n }\n let after=(&pinned.file).stream_position().unwrap();\n serde_json::json!({\"phase\":\"fence\",\"accepted\":error.is_none(),\"error\":error,\n  \"record_wire_hex\":__hia_anchor_hex(&wire),\"original_bytes_hex\":__hia_anchor_hex(&original),\n  \"cursor_before\":position,\"cursor_after\":after,\"completed\":completed,\"read_callbacks\":callbacks})\n}\n"
AUDIT_APPEND="\n// Qualification-only reachability; every original anchor function is unchanged.\n#[doc(hidden)]\npub fn __hia_durable_archive_anchor_fs_original(value:&serde_json::Value)->serde_json::Value{\n archive_store::__hia_archive_anchor_fs_original(value)\n}\n"
BIN="use std::io::{BufRead,Write};\nfn main()->std::io::Result<()>{\n let mut output=std::io::stdout().lock();\n for line in std::io::stdin().lock().lines(){\n  let value:serde_json::Value=serde_json::from_str(&line?).unwrap();\n  let result=hepta_runtime::mcp::runtime::request_audit::__hia_durable_archive_anchor_fs_original(&value);\n  writeln!(output,\"{}\",serde_json::to_string(&result).unwrap())?;output.flush()?;\n }\n Ok(())\n}\n"
def literals(path,pin):
 raw=path.read_bytes();assert SHA(raw)==pin
 return {t.id:ast.literal_eval(n.value)for n in ast.parse(raw).body if isinstance(n,ast.Assign)for t in n.targets if isinstance(t,ast.Name)and t.id in{"APPEND","STORE_APPEND","AUDIT_APPEND","BIN"}}
def main():
 p=argparse.ArgumentParser();p.add_argument("--project",type=Path,required=True);p.add_argument("--history-preparer",type=Path,required=True);p.add_argument("--records-preparer",type=Path,required=True);a=p.parse_args();root=a.project
 history=literals(a.history_preparer,"844713331bb1b0ea0713cfc57622f0f363767f38dcb986b408c2d01cf35892ae")
 records=literals(a.records_preparer,"f94091c91999da81d28178a79697aa87a0f7453bf8b3c0aa6bd145773bf2277a")
 originals={n:(root/"audit_current_history"/("original-"+n.replace("/","__"))).read_bytes()for n in list(PINS)[:3]}
 originals["src/mcp/runtime/request_archive_store.rs"]=(root/"audit_archive_records/before-src__mcp__runtime__request_archive_store.rs").read_bytes()
 originals["src/mcp/runtime/request_archive_store_tests.rs"]=(root/"src/mcp/runtime/request_archive_store_tests.rs").read_bytes()
 for n,v in originals.items():assert SHA(v)==PINS[n],n
 expected=dict(originals)
 expected["Cargo.toml"]+=b'\n[[bin]]\nname = "hia-durable-audit-history-original"\npath = "audit_current_history/oracle.rs"\n'+b'\n[[bin]]\nname = "hia-durable-archive-records-original"\npath = "audit_archive_records/oracle.rs"\n'
 expected["src/mcp/runtime/request_audit.rs"]+=history["APPEND"].encode()+records["AUDIT_APPEND"].encode()
 expected["src/mcp/runtime/request_archive_store.rs"]+=records["STORE_APPEND"].encode()
 before={n:(root/n).read_bytes()for n in PINS};assert before==expected
 q=root/"audit_anchor_fs";q.mkdir(exist_ok=False)
 for n,v in before.items():(q/("before-"+n.replace("/","__"))).write_bytes(v)
 (q/"oracle.rs").write_text(BIN)
 for n,v in [("src/mcp/runtime/request_audit.rs",AUDIT_APPEND),("src/mcp/runtime/request_archive_store.rs",STORE_APPEND)]:
  with(root/n).open("ab")as f:f.write(v.encode())
 with(root/"Cargo.toml").open("ab")as f:f.write(b'\n[[bin]]\nname = "hia-durable-archive-anchor-original"\npath = "audit_anchor_fs/oracle.rs"\n')
 for n,v in before.items():assert(root/n).read_bytes().startswith(v),n
 assert(root/"Cargo.lock").read_bytes()==originals["Cargo.lock"]and(root/"src/mcp/runtime/request_archive_store_tests.rs").read_bytes()==originals["src/mcp/runtime/request_archive_store_tests.rs"]
 report=dict(schema="hepta.runtime.durable-anchor-original.v1",original_commit="abc9ecb95ee9538518ec3f36c47b881974107021",original=PINS,
  before={n:dict(bytes=len(v),sha256=SHA(v))for n,v in before.items()},after={n:dict(bytes=len(v),sha256=SHA(v))for n in PINS for v in[(root/n).read_bytes()]},
  original_functions_whole_bytes_preserved=True,original_tests_whole_bytes_preserved=True,graph_profile_default_features_unchanged=True,
  append_sha256={"audit":SHA(AUDIT_APPEND.encode()),"store":SHA(STORE_APPEND.encode()),"bin":SHA(BIN.encode())},
  scope="actual original PinnedAnchor open/fence/fence_with; mutations only in explicit QA closures; exact retained descriptor, full bytes, complete eleven-field stamp; no archive query/public admission claim")
 (q/"source-relation.json").write_text(json.dumps(report,sort_keys=True,indent=2)+"\n");print(json.dumps(report,sort_keys=True),flush=True)
if __name__=="__main__":main()
